"""Static, reproducible charts generated by the batch pipeline."""

from __future__ import annotations

import os
from pathlib import Path

_mpl_config_dir = Path(__file__).resolve().parents[1] / ".cache" / "matplotlib"
_mpl_config_dir.mkdir(parents=True, exist_ok=True)
os.environ.setdefault("MPLCONFIGDIR", str(_mpl_config_dir))

import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from matplotlib.ticker import PercentFormatter

from src.analytics import summarize_segments


COLORS = {0: "#547A9B", 1: "#D66A55"}


def _finish(fig: plt.Figure, path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    fig.tight_layout()
    fig.savefig(path, dpi=160, bbox_inches="tight", facecolor="white")
    plt.close(fig)
    return path


def _rate_plot(ax: plt.Axes, frame: pd.DataFrame, column: str, title: str) -> None:
    summary = summarize_segments(frame, column)
    ax.bar(summary["segment"].astype(str), summary["churn_rate"] * 100, color="#547A9B")
    ax.set_title(title, loc="left", fontsize=11, weight="bold")
    ax.set_ylabel("Churn rate (%)")
    ax.tick_params(axis="x", rotation=25)
    ax.grid(axis="y", alpha=0.2)


def generate_figures(frame: pd.DataFrame, output_dir: str | Path) -> list[Path]:
    """Save the report-ready visual set and return all generated paths."""
    target = Path(output_dir)
    target.mkdir(parents=True, exist_ok=True)
    generated: list[Path] = []

    counts = frame["Exited"].value_counts().reindex([0, 1], fill_value=0)
    fig, ax = plt.subplots(figsize=(7, 4))
    ax.bar(["Retained", "Churned"], counts.values, color=[COLORS[0], COLORS[1]])
    ax.set_title("Customer outcome distribution", loc="left", fontsize=14, weight="bold")
    ax.set_ylabel("Customers")
    ax.grid(axis="y", alpha=0.2)
    generated.append(_finish(fig, target / "overall_churn.png"))

    geo = summarize_segments(frame, "Geography")
    fig, axes = plt.subplots(1, 2, figsize=(11, 4))
    axes[0].bar(geo["segment"], geo["churn_rate"] * 100, color="#547A9B")
    axes[0].axhline(frame["Exited"].mean() * 100, color="#D66A55", linestyle="--", label="Portfolio rate")
    axes[0].set_title("Churn rate by country", loc="left", weight="bold")
    axes[0].set_ylabel("Churn rate (%)")
    axes[0].legend(frameon=False)
    axes[1].bar(geo["segment"], geo["churn_contribution"] * 100, color="#79A695")
    axes[1].set_title("Share of churners by country", loc="left", weight="bold")
    axes[1].set_ylabel("Contribution to churn (%)")
    for ax in axes:
        ax.grid(axis="y", alpha=0.2)
    generated.append(_finish(fig, target / "geography_churn.png"))

    fig, axes = plt.subplots(1, 2, figsize=(12, 4))
    _rate_plot(axes[0], frame, "AgeSegment", "Churn by age segment")
    _rate_plot(axes[1], frame, "TenureGroup", "Churn by tenure group")
    generated.append(_finish(fig, target / "age_tenure_churn.png"))

    fig, axes = plt.subplots(1, 2, figsize=(12, 4))
    _rate_plot(axes[0], frame, "CreditScoreSegment", "Churn by credit-score segment")
    _rate_plot(axes[1], frame, "BalanceSegment", "Churn by balance segment")
    generated.append(_finish(fig, target / "credit_balance_churn.png"))

    fig, axes = plt.subplots(1, 3, figsize=(15, 4))
    _rate_plot(axes[0], frame, "Gender", "Churn by gender")
    activity = frame.assign(Activity=np.where(frame["IsActiveMember"] == 1, "Active", "Inactive"))
    _rate_plot(axes[1], activity.rename(columns={"Activity": "ActivityGroup"}), "ActivityGroup", "Churn by activity")
    products = frame.assign(ProductGroup=frame["NumOfProducts"].map(lambda value: "3+ products" if value >= 3 else f"{value} product" if value == 1 else "2 products"))
    _rate_plot(axes[2], products, "ProductGroup", "Churn by product count")
    generated.append(_finish(fig, target / "demographics_engagement_products.png"))

    pivot = frame.pivot_table(index="Geography", columns="AgeSegment", values="Exited", aggfunc="mean", observed=True)
    fig, ax = plt.subplots(figsize=(8, 4.5))
    image = ax.imshow(pivot.to_numpy() * 100, cmap="YlOrRd", aspect="auto", vmin=0)
    ax.set_xticks(range(len(pivot.columns)), [str(value) for value in pivot.columns])
    ax.set_yticks(range(len(pivot.index)), [str(value) for value in pivot.index])
    ax.set_title("Churn rate by geography and age", loc="left", fontsize=13, weight="bold")
    for row in range(len(pivot.index)):
        for col in range(len(pivot.columns)):
            value = pivot.iloc[row, col]
            if pd.notna(value):
                ax.text(col, row, f"{value:.1%}", ha="center", va="center", fontsize=9)
    fig.colorbar(image, ax=ax, label="Churn rate (%)")
    generated.append(_finish(fig, target / "geography_age_heatmap.png"))

    fig, axes = plt.subplots(1, 3, figsize=(15, 4))
    for ax, column, title in zip(axes, ["Balance", "EstimatedSalary", "CreditScore"], ["Balance", "Estimated salary", "Credit score"]):
        for outcome, label in ((0, "Retained"), (1, "Churned")):
            values = frame.loc[frame["Exited"] == outcome, column].dropna()
            if not values.empty:
                ax.hist(values, bins=25, alpha=0.58, density=True, color=COLORS[outcome], label=label)
        ax.set_title(title, loc="left", weight="bold")
        ax.set_ylabel("Density")
        ax.legend(frameon=False)
        ax.grid(axis="y", alpha=0.2)
    generated.append(_finish(fig, target / "financial_distributions.png"))

    hv = summarize_segments(frame, "HighValueCustomer")
    exposure = frame.groupby("HighValueCustomer", observed=True)["Balance"].sum()
    fig, axes = plt.subplots(1, 2, figsize=(10, 4))
    axes[0].bar(hv["segment"].astype(str), hv["churn_rate"] * 100, color=["#547A9B", "#D66A55"][: len(hv)])
    axes[0].set_title("High-balance proxy churn rate", loc="left", weight="bold")
    axes[0].set_ylabel("Churn rate (%)")
    labels = ["High-value proxy" if bool(value) else "Other customers" for value in exposure.index]
    axes[1].bar(labels, exposure.values, color="#79A695")
    axes[1].set_title("Balance held by each group", loc="left", weight="bold")
    axes[1].set_ylabel("Balance exposure (dataset units)")
    axes[1].tick_params(axis="x", rotation=15)
    for ax in axes:
        ax.grid(axis="y", alpha=0.2)
    generated.append(_finish(fig, target / "high_value_exposure.png"))

    product_activity = frame.pivot_table(
        index="NumOfProducts", columns="ActivityLabel", values="Exited", aggfunc="mean", observed=True
    )
    fig, ax = plt.subplots(figsize=(8, 4.5))
    product_activity.plot(kind="bar", ax=ax, color=["#D66A55", "#547A9B"][: len(product_activity.columns)])
    ax.set_title("Churn by product count and member activity", loc="left", fontsize=13, weight="bold")
    ax.set_xlabel("Number of products")
    ax.set_ylabel("Churn rate")
    ax.yaxis.set_major_formatter(PercentFormatter(1))
    ax.legend(title="Activity", frameon=False)
    ax.grid(axis="y", alpha=0.2)
    generated.append(_finish(fig, target / "product_activity_interaction.png"))

    pivot = frame.pivot_table(index="NumOfProducts", columns="ActivityLabel", values="Exited", aggfunc="mean", observed=True)
    counts = frame.pivot_table(index="NumOfProducts", columns="ActivityLabel", values="Exited", aggfunc="size", observed=True)
    counts = counts.reindex(index=pivot.index, columns=pivot.columns)
    fig, ax = plt.subplots(figsize=(8, 4.5))
    image = ax.imshow(pivot.to_numpy() * 100, cmap="Blues", aspect="auto")
    ax.set_xticks(range(len(pivot.columns)), [str(value) for value in pivot.columns])
    ax.set_yticks(range(len(pivot.index)), [str(value) for value in pivot.index])
    ax.set_title("Product × activity segment risk matrix", loc="left", weight="bold")
    for row in range(len(pivot.index)):
        for col in range(len(pivot.columns)):
            rate = pivot.iloc[row, col]
            count = counts.iloc[row, col]
            if pd.notna(rate):
                ax.text(col, row, f"{rate:.1%}\nn={int(count):,}", ha="center", va="center", fontsize=9)
    fig.colorbar(image, ax=ax, label="Segment churn rate (%)")
    generated.append(_finish(fig, target / "segment_risk_matrix.png"))

    return generated
